export type CommuneType = 'xã' | 'phường' | 'đặc khu';

export interface Commune {
  /** Mã đơn vị hành chính cấp xã (5 chữ số). */
  code: string;
  /** Tên không kèm loại, viết như danh mục chính thức, ví dụ 'Đồng Xoài', 'Ba Đình'. */
  name: string;
  type: CommuneType;
}

export interface Province {
  /** Mã cấp tỉnh (2 chữ số). */
  code: string;
  /** Tên không kèm loại, ví dụ 'Hà Nội', 'Đồng Nai'. */
  name: string;
  type: 'tỉnh' | 'thành phố';
  communes: Commune[];
}

